1	/** Minimal static file server for the Bombadil harness (no dependencies). */
2	import { createServer } from 'node:http';
3	import { readFile } from 'node:fs/promises';
4	import { extname, join, normalize } from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	
7	const ROOT = fileURLToPath(new URL('..', import.meta.url));
8	const PORT = Number(process.env.PBT_PORT ?? 8199);
9	const MIME = {
10	    '.css': 'text/css',
11	    '.html': 'text/html',
12	    '.js': 'text/javascript',
13	    '.json': 'application/json',
14	    '.mjs': 'text/javascript'
15	};
16	
17	const server = createServer(async (req, res) => {
18	    const url = new URL(req.url, `http://127.0.0.1:${PORT}`);
19	    if (url.pathname === '/favicon.ico') {
20	        res.writeHead(204);
21	        res.end();
22	        return;
23	    }
24	    let path = normalize(url.pathname).replace(/^(\.\.[/\\])+/, '');
25	    if (path.endsWith('/')) {
26	        path = `${path}index.html`;
27	    }
28	    // The cards navigate via history.pushState to virtual Home Assistant
29	    // routes (e.g. /config/integrations/...), and a browser reload then
30	    // requests that route from this server. Serve the harness page for any
31	    // extensionless path — mirroring the real frontend's single-page-app
32	    // routing — while keeping honest 404s for missing assets.
33	    if (!extname(path)) {
34	        path = '/pbt/harness/index.html';
35	    }
36	    try {
37	        const body = await readFile(join(ROOT, path));
38	        res.writeHead(200, {
39	            'Content-Type': MIME[extname(path)] ?? 'application/octet-stream'
40	        });
41	        res.end(body);
42	    } catch {
43	        res.writeHead(404);
44	        res.end('not found');
45	    }
46	});
47	
48	server.listen(PORT, '127.0.0.1', () => {
